draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // thesis
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/4, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 - 20);
  ctx.lineTo(W/4, H/2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4 - 20, H/2);
  ctx.lineTo(W/4 + 20, H/2);
  ctx.stroke();
  ctx.font = '20px Arial';
  ctx.fillStyle = 'black';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillText('Thesis', W/4, H/2 + 30);

  // antithesis
  ctx.beginPath();
  ctx.arc(W - W/4, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 - 20);
  ctx.lineTo(W - W/4, H/2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4 - 20, H/2);
  ctx.lineTo(W - W/4 + 20, H/2);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillText('Antithesis', W - W/4, H/2 + 30);

  // synthesis
  ctx.beginPath();
  ctx.arc(W/2, H/2 + Math.sin(t) * 50, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + Math.sin(t) * 50 - 20);
  ctx.lineTo(W/2, H/2 + Math.sin(t) * 50 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 20, H/2 + Math.sin(t) * 50);
  ctx.lineTo(W/2 + 20, H/2 + Math.sin(t) * 50);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillText('Synthesis', W/2, H/2 + Math.sin(t) * 50 + 30);

  // dialectic
  ctx.beginPath();
  ctx.moveTo(W/4, H/2);
  ctx.lineTo(W/2, H/2 + Math.sin(t) * 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2);
  ctx.lineTo(W/2, H/2 + Math.sin(t) * 50);
  ctx.stroke();

  ctx.restore();
}
